A.flowGo=el=>{const r=el.dataset.r;if(el.dataset.pre){UI.exTab='s';UI.exF.s={...exDef('s'),...JSON.parse(el.dataset.pre)};if(location.hash==='#'+r)setTimeout(()=>render(true),50)}const need=ROLEOF[r.split('-')[0]];if(need)S.role=need;else if(S.role!=='customer'&&!['aappr','aaudit'].includes(r)){}if(['ronboard','vonboard','sonboard'].includes(r))S.role=r==='ronboard'?'rider':'vendor';save()};
/* motion demos */
A.mAdd=()=>{const b=$('#m1');b.animate([{transform:'scale(1)'},{transform:'scale(1.12)'},{transform:'scale(1)'}],{duration:260,easing:'cubic-bezier(.2,.8,.2,1)'})};
A.mHeart=()=>{const b=$('#m2');b.style.color='var(--error)';b.querySelector('svg').style.fill='var(--error)';b.animate([{transform:'scale(1)'},{transform:'scale(1.4)'},{transform:'scale(1)'}],{duration:320})};
A.mStar=()=>{let i=0;const s=$('#m3');const iv=setInterval(()=>{i++;s.innerHTML=stars(i,24);if(i>=5)clearInterval(iv)},120)};
