A.dsSheet=()=>sheet(`<h3>Bottom sheet</h3><p class="t2">On mobile it slides up from the bottom; on desktop it becomes a centred modal. Esc or the scrim closes it.</p><button class="btn p block" data-act="closeSheet">Done</button>`);
A.dsConfirm=()=>confirmBox('Delete this item?','This cannot be undone.','Delete',()=>toast('Deleted'),true);A.dsToast=()=>toast('Saved to bookmarks','bookmark');
