A.dsPop=el=>{const r=el.getBoundingClientRect();const p=document.createElement('div');p.className='card pad';p.style.cssText=`position:fixed;left:${clamp(r.left,8,innerWidth-230)}px;top:${r.bottom+6}px;z-index:150;width:220px;box-shadow:var(--sh-3)`;p.innerHTML='Popover anchored to its trigger. Click elsewhere to close.';document.body.appendChild(p);setTimeout(()=>document.addEventListener('click',()=>p.remove(),{once:true}),10)};
