function tokensJson(){const o={color:{light:{},dark:{}},typography:{display:'Poppins 700',body:'Noto Sans / Noto Sans Devanagari',sizes:{display:'32/40|48/56',h1:'28/35|35/44',h2:'22/28|26/33',h3:'18/23',body:'16/24',small:'14/21',caption:'12.5/18'}},spacing:[4,8,12,16,24,32,48,64],radius:{xs:6,sm:10,md:14,lg:20,pill:999},shadow:{1:'0 1px 2px rgba(60,40,20,.08)',2:'0 4px 12px rgba(60,40,20,.10)',3:'0 16px 40px rgba(60,40,20,.18)'},motion:{dur:{1:'120ms',2:'220ms',3:'380ms'},ease:'cubic-bezier(.2,.8,.2,1)'},breakpoints:{tablet:600,desktop:900,container:1200}};PAL.forEach(([n,k,l,d])=>{o.color.light[k]=l;o.color.dark[k]=d});Object.entries(TOK.light).forEach(([k,v])=>o.color.light[k]=v);Object.entries(TOK.dark).forEach(([k,v])=>o.color.dark[k]=v);ORD.forEach(([n,k,l,d])=>{o.color.light['status-'+k]=l;o.color.dark['status-'+k]=d});APR.forEach(([n,k,l,d])=>{o.color.light['approval-'+k]=l;o.color.dark['approval-'+k]=d});return o}
